#if UNITY_EDITOR
using System;using System.Collections;using System.Reflection;using System.IO;using System.Collections.Generic;using UnityEngine;
public class DigitalKingdomValidation:MonoBehaviour {
 DungeonPrototype d;MethodInfo draw;bool mirror;
 void Awake(){d=GetComponent<DungeonPrototype>();draw=typeof(DungeonPrototype).GetMethod("OnGUI",BindingFlags.Instance|BindingFlags.NonPublic);}
 void OnGUI(){if(mirror&&d!=null&&!d.enabled)draw.Invoke(d,null);}
 public void Run(){StartCoroutine(Check());}
 IEnumerator Check(){var f=BindingFlags.Instance|BindingFlags.NonPublic;var t=typeof(DungeonPrototype);var original=d.CaptureDungeonSave();bool wasEnabled=d.enabled;string oldPath=DungeonSaveStore.editorTestPath;int oldWidth=Screen.width,oldHeight=Screen.height;var results=new List<string>();Action<bool,string> check=(ok,label)=>results.Add((ok?"PASS ":"FAIL ")+label);var dialogue=(WorldDialogue)t.GetField("worldDialogue",f).GetValue(d);Action finish=()=>{int safety=0;while(dialogue.Active&&safety++<40){dialogue.CompleteLetters();dialogue.Advance(50);}};
  d.enabled=false;mirror=true;
  try{
   var map=DungeonMapSettings.Current;var entrance=map.entities.objects.Find(e=>e.cityEntrance);var data=JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(original));data.introductionCompleted=true;data.cell=entrance.cell;data.heading=entrance.heading;data.city=new DigitalKingdomProgress();data.refuge.refugeTragedyTriggered=false;data.refuge.unlockedNodes=new List<string>{"node.refuge"};var boss=data.enemies.Find(r=>r.placementId==DigitalKingdomSettings.Current.requiredBossId);if(boss==null)throw new Exception("La fixture no contiene Makong.");boss.defeated=false;boss.currentHP=Mathf.Max(1,boss.currentHP);d.RestoreDungeonSave(data);t.GetField("startMenuOpen",f).SetValue(d,false);
   check(!d.EnterDigitalKingdom(),"Acceso bloqueado antes de derrotar Makong");boss.defeated=true;boss.currentHP=0;d.RestoreDungeonSave(data);t.GetField("startMenuOpen",f).SetValue(d,false);var doors=(Dictionary<string,DungeonDoor>)t.GetField("mapDoors",f).GetValue(d);var door=doors[entrance.id];door.SetOpenImmediately();yield return d.StartCoroutine((IEnumerator)t.GetMethod("Move",f).Invoke(d,new object[]{1,0}));
   check((bool)t.GetField("cityActive",f).GetValue(d),"Cruzar puerta real abre ciudad");check(Time.timeScale==0,"Dungeon suspendido y sin turnos extra");var view=(Camera)t.GetField("view",f).GetValue(d);check(view.cullingMask==0,"Vista ciudad sin mundo 3D ni HUD dungeon");finish();var progress=(DigitalKingdomProgress)t.GetField("cityProgress",f).GetValue(d);check(progress.firstVisitCompleted,"Primera visita completada");check(progress.returnCell==entrance.cell,"Retorno guarda entrada real");
   foreach(var l in DigitalKingdomSettings.Current.locations){if(l.service==DigitalKingdomService.Exit)continue;check(d.OpenCityLocation(l.id),"Establecimiento abre: "+l.displayName);finish();t.GetMethod("LeaveCityLocation",f).Invoke(d,null);check(string.IsNullOrEmpty(progress.locationId),"Establecimiento vuelve al hub: "+l.id);}
   t.GetField("hp",f).SetValue(d,1);d.OpenCityLocation("city.temple");finish();d.RegisterCityTemple();var healed=d.CaptureDungeonSave();check(healed.player.currentHP==(int)t.GetProperty("MaximumHP",f).GetValue(d)&&progress.templeRegistered,"Temple cura y registra Continue");
   Directory.CreateDirectory("Tests");DungeonSaveStore.editorTestPath=Path.GetFullPath("Tests/CityHubSave.json");DungeonSaveStore.Write(healed,0,"City MCP fixture");var loaded=DungeonSaveStore.Read(0);d.RestoreDungeonSave(loaded);progress=(DigitalKingdomProgress)t.GetField("cityProgress",f).GetValue(d);check((bool)t.GetField("cityActive",f).GetValue(d)&&progress.templeRegistered&&progress.conversationsSeen.Count>=6,"Guardar/cargar preserva ciudad, Continue y conversaciones");
   var nodes=(List<TransferNodeDefinition>)t.GetMethod("CityTravelNodes",f).Invoke(d,null);check(nodes.Count==1&&nodes[0].id=="node.refuge","Fast Travel muestra solo nodo descubierto");check(!(bool)t.GetMethod("CityTravel",f).Invoke(d,new object[]{"node.zone2"}),"Viaje a nodo bloqueado rechazado");check(d.OpenCityLocation("city.lab"),"Bug Lab accesible");finish();t.GetMethod("ExecuteCityService",f).Invoke(d,new object[]{0});check(dialogue.Active&&dialogue.Current.text.Contains("development"),"Servicio futuro presenta placeholder");finish();t.GetMethod("LeaveCityLocation",f).Invoke(d,null);
   var before=d.CaptureDungeonSave();check(d.OpenCityLocation("city.exit"),"Exit City seleccionable");check(!(bool)t.GetField("cityActive",f).GetValue(d)&&(Vector2Int)t.GetField("position",f).GetValue(d)==entrance.cell,"Exit retorna al dungeon correcto");check(view.cullingMask!=0&&Time.timeScale==1,"Cámara y reloj restaurados");var after=d.CaptureDungeonSave();check(before.enemies.Count==after.enemies.Count&&before.entityStates.Count==after.entityStates.Count&&before.explored.Count==after.explored.Count,"Salir conserva enemigos, cofres/puertas y mapa");
   yield return d.StartCoroutine((IEnumerator)t.GetMethod("Move",f).Invoke(d,new object[]{1,0})); // facing south: leave gate area
   t.GetMethod("WarpPlayer",f).Invoke(d,new object[]{entrance.cell,entrance.heading});yield return d.StartCoroutine((IEnumerator)t.GetMethod("Move",f).Invoke(d,new object[]{1,0}));check((bool)t.GetField("cityActive",f).GetValue(d)&&!dialogue.Active,"Revisita por puerta sin repetir descubrimiento");d.ExitDigitalKingdom();
   t.GetField("lost",f).SetValue(d,true);t.GetField("hp",f).SetValue(d,0);check((bool)t.GetMethod("TryCityRespawn",f).Invoke(d,null),"Derrota regresa al Temple");check(!(bool)t.GetField("lost",f).GetValue(d)&&d.CaptureDungeonSave().player.currentHP>0,"Continue sin bucle de derrota");finish();t.GetMethod("LeaveCityLocation",f).Invoke(d,null);
   t.GetField("cityTransition",f).SetValue(d,Time.unscaledTime-1);Directory.CreateDirectory("Captures/DigitalKingdom");ScreenCapture.CaptureScreenshot("Captures/DigitalKingdom/City.png");yield return new WaitForEndOfFrame();
  }finally{d.StopAllCoroutines();d.RestoreDungeonSave(original);d.enabled=wasEnabled;mirror=false;DungeonSaveStore.editorTestPath=oldPath;Directory.CreateDirectory("Tests");File.WriteAllLines("Tests/DigitalKingdomMcpResults.txt",results);Debug.Log("City tests finished\n"+string.Join("\n",results.ToArray()));}
 }
 public void InputChecks(){StartCoroutine(CheckInputs());}
 IEnumerator CheckInputs(){yield return null;var f=BindingFlags.Instance|BindingFlags.NonPublic;var t=typeof(DungeonPrototype);var original=d.CaptureDungeonSave();var data=JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(original));var entry=DungeonMapSettings.Current.entities.objects.Find(e=>e.cityEntrance);data.cell=entry.cell;data.introductionCompleted=true;data.city=new DigitalKingdomProgress{discovered=true,firstVisitCompleted=true};var boss=data.enemies.Find(e=>e.placementId==DigitalKingdomSettings.Current.requiredBossId);boss.defeated=true;boss.currentHP=0;d.enabled=false;mirror=true;d.RestoreDungeonSave(data);t.GetField("startMenuOpen",f).SetValue(d,false);d.EnterDigitalKingdom();string results="";
  var keyboard=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>();var pad=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Gamepad>();
  try{
   UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState(UnityEngine.InputSystem.Key.DownArrow));UnityEngine.InputSystem.InputSystem.Update();keyboard.MakeCurrent();t.GetMethod("UpdateCityInput",f).Invoke(d,null);results+="keyboardDown="+((int)t.GetField("citySelection",f).GetValue(d)==1)+"\n";
   yield return null;UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState());UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState().WithButton(UnityEngine.InputSystem.LowLevel.GamepadButton.DpadDown));UnityEngine.InputSystem.InputSystem.Update();pad.MakeCurrent();t.GetMethod("UpdateCityInput",f).Invoke(d,null);results+="gamepadDown="+((int)t.GetField("citySelection",f).GetValue(d)==2)+"\n";
   yield return null;UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState().WithButton(UnityEngine.InputSystem.LowLevel.GamepadButton.South));UnityEngine.InputSystem.InputSystem.Update();t.GetMethod("UpdateCityInput",f).Invoke(d,null);var progress=(DigitalKingdomProgress)t.GetField("cityProgress",f).GetValue(d);results+="gamepadConfirm="+(progress.locationId=="city.temple")+"\n";
   var dialog=(WorldDialogue)t.GetField("worldDialogue",f).GetValue(d);for(int n=0;n<30&&dialog.Active;n++){dialog.CompleteLetters();dialog.Advance(50);}yield return null;UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState().WithButton(UnityEngine.InputSystem.LowLevel.GamepadButton.East));UnityEngine.InputSystem.InputSystem.Update();t.GetMethod("UpdateCityInput",f).Invoke(d,null);results+="gamepadBack="+string.IsNullOrEmpty(progress.locationId)+"\n";
  }finally{UnityEngine.InputSystem.InputSystem.RemoveDevice(keyboard);UnityEngine.InputSystem.InputSystem.RemoveDevice(pad);d.RestoreDungeonSave(original);d.enabled=true;mirror=false;File.WriteAllText("Tests/DigitalKingdomInputResults.txt",results);Debug.Log("City inputs\n"+results);}
 }

}
#endif
